// Standard single-disk ZIPs generated by tools/make_pack.py. Read entries on demand.
const utf8 = new TextDecoder();
const view = async blob => new DataView(await blob.arrayBuffer());

async function directory(file) {
  const tail = await view(file.slice(Math.max(0, file.size - 65557)));
  let e = tail.byteLength - 22;
  while (e >= 0 && tail.getUint32(e, true) !== 0x06054b50) e--;
  if (e < 0) throw Error('Выберите ZIP, собранный для Warcraft III.');
  const count = tail.getUint16(e+10, true);
  const length = tail.getUint32(e+12, true), offset = tail.getUint32(e+16, true);
  if (length > 32*1024*1024 || offset+length > file.size || tail.getUint32(e+4, true)) {
    throw Error('Этот формат ZIP не поддерживается.');
  }
  const central = await view(file.slice(offset, offset+length));
  const entries = new Map();
  let pos = 0;
  for (let i = 0; i < count; i++) {
    if (pos+46 > length || central.getUint32(pos, true) !== 0x02014b50) throw Error('Повреждён каталог ZIP.');
    const n = central.getUint16(pos+28, true);
    const name = utf8.decode(new Uint8Array(central.buffer, pos+46, n));
    const method = central.getUint16(pos+10, true);
    if (method !== 0 && method !== 8) throw Error('Пакет должен использовать ZIP Store или Deflate.');
    entries.set(name, {
      method, size:central.getUint32(pos+24, true), packed:central.getUint32(pos+20, true),
      offset:central.getUint32(pos+42, true)
    });
    pos += 46+n+central.getUint16(pos+30, true)+central.getUint16(pos+32, true);
  }
  if (!entries.has('warcraft3-pack.json') || !entries.has('gamedata/maps.index.txt')) {
    throw Error('Нужен игровой ZIP, созданный командой tools/make_pack.py.');
  }
  return entries;
}

async function payload(file, entry) {
  const h = await view(file.slice(entry.offset, entry.offset+30));
  if (h.getUint32(0, true) !== 0x04034b50) throw Error('Повреждена запись ZIP.');
  const start = entry.offset + 30 + h.getUint16(26, true) + h.getUint16(28, true);
  if (start+entry.packed > file.size) throw Error('Пакет обрывается до конца файла.');
  const blob = file.slice(start, start+entry.packed);
  return entry.method === 0 ? blob :
    new Response(blob.stream().pipeThrough(new DecompressionStream('deflate-raw'))).blob();
}

async function packStore(mode, action) {
  const db = await new Promise((resolve, reject) => {
    const r = indexedDB.open('warcraft3-local-pack', 1);
    r.onupgradeneeded = () => r.result.createObjectStore('game');
    r.onerror = () => reject(r.error);
    r.onsuccess = () => resolve(r.result);
  });
  try {
    return await new Promise((resolve, reject) => {
      const tx = db.transaction('game', mode);
      const request = action(tx.objectStore('game'));
      tx.oncomplete = () => resolve(request.result);
      tx.onabort = () => reject(tx.error || Error('Хранилище недоступно.'));
    });
  } finally { db.close(); }
}

async function inspectPack(file) {
  const entries = await directory(file);
  const description = entries.get('warcraft3-pack.json');
  if (description.size > 64*1024) throw Error('Повреждён манифест игрового пакета.');
  const manifest = JSON.parse(await (await payload(file, description)).text());
  if (manifest.format !== 1 || (manifest.startMap && !entries.has('gamedata/' + manifest.startMap))) {
    throw Error('Пакет несовместим или карта запуска отсутствует.');
  }
  const art = {};
  for (const name of ['background.webp','roc.webp','tft.webp','border.png','fill.png','icon-192.png','icon-512.png','font.ttf','button.webp']) {
    const entry = entries.get('presentation/' + name);
    if (entry && entry.size < 4*1024*1024) art[name] = await payload(file, entry);
  }
  return {manifest, art};
}

async function installedArchive(row) {
  if (row.file) return row.file; // ZIP chosen from the system file picker.
  if (!Array.isArray(row.chunkKeys) || !row.chunkKeys.length) throw Error('Пакет игры отсутствует.');
  let requests;
  await packStore('readonly',store=>{
    requests=row.chunkKeys.map(k=>store.get(k));
    return requests[requests.length-1];
  });
  const blocks=requests.map(r=>r.result);
  if (blocks.some(b=>!(b instanceof Blob))) throw Error('Файлы установки неполны. Откройте страницу загрузки.');
  // Blob concatenation references the on-disk blocks. No second full ZIP is stored.
  return new Blob(blocks,{type:'application/zip'});
}
